diff --git a/tmp-repro/input.js b/tmp-repro/input.js
new file mode 100644
index 0000000..a2a10d9
--- /dev/null
+++ b/tmp-repro/input.js
@@ -0,0 +1,5 @@
+export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
diff --git a/tmp-repro/repro.js b/tmp-repro/repro.js
new file mode 100644
index 0000000..43d25b1
--- /dev/null
+++ b/tmp-repro/repro.js
@@ -0,0 +1,16 @@
+"use strict";
+// Usage: node repro.js [path-to-eslint-package]
+const { Linter } = require(process.argv[2] || "..");
+const fs = require("fs");
+const code = fs.readFileSync(__dirname + "/input.js", "utf8");
+const linter = new Linter();
+const config = [{ rules: { "no-var": "error" } }];
+const msgs = linter.verify(code, config);
+const out = linter.verifyAndFix(code, config).output;
+console.log("version:", Linter.version);
+console.log("messages:", msgs.map(m => `${m.line}:${m.column} ${m.message} (${m.ruleId}) fix=${!!m.fix}`));
+console.log("fixed output:\n" + out);
+// Execute the fixed function to see whether it throws
+const body = out.replace("export ", "") + "\na();";
+try { new Function(body)(); console.log("RESULT: fixed code runs OK"); }
+catch (e) { console.log("RESULT: fixed code throws", e.name + ":", e.message); }
